// GloamingForest - The Twilight Forest for Minecraft: Bedrock Edition.
// Tests of the landmark grid (F6), a translation of TF's LegacyLandmarkPlacements
// (TeamTwilight/twilightforest @ 9e40a757, LGPL-2.1-or-later), against goldens generated by an
// independent Java-semantics reference (golden/grid_reference.js).
#include <gtest/gtest.h>

#include <map>
#include <string>
#include <utility>
#include <vector>

#include "core/landmark/Grid.h"
#include "core/landmark/Landmark.h"

namespace {
#include "golden/GridGolden.inc"
} // namespace

using namespace gf::core::landmark;

TEST(LandmarkGrid, NearestCenterMatchesGoldens) {
    for (auto const& r : kCenterRows) {
        auto c = nearestCenter(r.cx, r.cz);
        EXPECT_EQ(c.x, r.x) << "chunk " << r.cx << "," << r.cz;
        EXPECT_EQ(c.z, r.z) << "chunk " << r.cx << "," << r.cz;
        EXPECT_EQ(chunkHasCenter(r.cx, r.cz), r.has) << "chunk " << r.cx << "," << r.cz;
        EXPECT_EQ(manhattanDistanceFromCenter(r.cx, r.cz), r.manhattan) << "chunk " << r.cx << "," << r.cz;
    }
}

TEST(LandmarkGrid, OriginCenterIsAtEightEight) {
    // region 0,0 has seed 0: no jitter, the center is block (8, 8) in chunk (0, 0)
    EXPECT_EQ(nearestCenter(0, 0), (ColumnXZ{8, 8}));
    EXPECT_TRUE(chunkHasCenter(0, 0));
    EXPECT_FALSE(chunkHasCenter(1, 0));
    EXPECT_TRUE(blockIsInCenter(8, 8));
    EXPECT_TRUE(blockIsInCenter(15, 0));
    EXPECT_FALSE(blockIsInCenter(16, 0));
}

TEST(LandmarkGrid, OneCenterPerRegion) {
    // every 16x16-chunk region (offset by 8 chunks) has exactly one center chunk
    for (int rx = -3; rx <= 3; ++rx) {
        for (int rz = -3; rz <= 3; ++rz) {
            int n = 0;
            for (int cx = rx * 16 - 8; cx < rx * 16 + 8; ++cx)
                for (int cz = rz * 16 - 8; cz < rz * 16 + 8; ++cz) n += chunkHasCenter(cx, cz) ? 1 : 0;
            EXPECT_EQ(n, 1) << "region " << rx << "," << rz;
        }
    }
}

TEST(LandmarkGrid, RoundRegionIsJavaMathRound) {
    for (auto const& r : kRoundRows) EXPECT_EQ(roundRegion(r.chunk), r.region) << "chunk " << r.chunk;
    EXPECT_EQ(roundRegion(8), 1);   // 0.5 rounds up
    EXPECT_EQ(roundRegion(-8), 0);  // -0.5 rounds up too
    EXPECT_EQ(roundRegion(-24), -1); // -1.5 -> -1
}

TEST(LandmarkGrid, VarietyPickMatchesGoldens) {
    for (auto const& r : kVarietyRows) EXPECT_EQ(pickVariety(r.seed, r.cx, r.cz), r.key) << "seed " << r.seed << " chunk " << r.cx << "," << r.cz;
}

TEST(LandmarkGrid, VarietyFixedLichTowersAndNagas) {
    // chunk region offsets (4,5) / (4,3) are lich towers, (5,4) / (3,4) naga courtyards, for every seed
    for (long long seed : {0LL, 42LL, -7LL}) {
        EXPECT_EQ(pickVariety(seed, 4 * 16 - 64, 5 * 16 - 64), "twilightforest:lich_tower");
        EXPECT_EQ(pickVariety(seed, 4 * 16 - 64, 3 * 16 - 64), "twilightforest:lich_tower");
        EXPECT_EQ(pickVariety(seed, 5 * 16 - 64, 4 * 16 - 64), "twilightforest:naga_courtyard");
        EXPECT_EQ(pickVariety(seed, 3 * 16 - 64, 4 * 16 - 64), "twilightforest:naga_courtyard");
    }
}

TEST(LandmarkGrid, VarietyWeightsAreTfs) {
    std::map<std::string, int> counts;
    for (int cx = -1600; cx < 1600; cx += 16)
        for (int cz = -1600; cz < 1600; cz += 16) counts[pickVariety(123456789LL, cx, cz)]++;
    // weighted 6:3:1:2:2:2 plus the fixed lich / naga regions: hollow hills dominate
    EXPECT_GT(counts["twilightforest:small_hollow_hill"], counts["twilightforest:medium_hollow_hill"]);
    EXPECT_GT(counts["twilightforest:medium_hollow_hill"], counts["twilightforest:large_hollow_hill"]);
    EXPECT_GT(counts["twilightforest:hedge_maze"], 0);
    EXPECT_EQ(counts.size(), 6u);
}

TEST(LandmarkGrid, PickForChunkUsesTheBiomeTable) {
    std::vector<std::pair<int, int>> sampled;
    auto biome = [&](std::string id) {
        return [&sampled, id](int x, int z) {
            sampled.emplace_back(x, z);
            return id;
        };
    };
    EXPECT_EQ(pickForChunk(0, 0, 0, biome("twilightforest:snowy_forest")), "twilightforest:yeti_cave");
    EXPECT_EQ(pickForChunk(0, 3, -2, biome("twilightforest:glacier")), "twilightforest:aurora_palace");
    EXPECT_EQ(pickForChunk(0, 0, 0, biome("twilightforest:lake")), "twilightforest:quest_island");
    EXPECT_EQ(pickForChunk(0, 0, 0, biome("twilightforest:final_plateau")), "twilightforest:final_castle");
    // the biome is sampled at the region center + 8
    ASSERT_FALSE(sampled.empty());
    EXPECT_EQ(sampled[0], (std::pair<int, int>{8, 8}));
    sampled.clear();
    (void)pickForChunk(0, 30, -20, biome("twilightforest:forest"));
    ASSERT_EQ(sampled.size(), 1u);
    EXPECT_EQ(sampled[0], (std::pair<int, int>{2 * 256 + 8, -1 * 256 + 8}));
    // other biomes: the variety pick
    EXPECT_EQ(pickForChunk(20260521LL, 40, -40, biome("twilightforest:forest")), pickVariety(20260521LL, 40, -40));
    EXPECT_EQ(biomeSampleColumn(30, -20), (ColumnXZ{2 * 256 + 8, -1 * 256 + 8}));
}

TEST(LandmarkGrid, CenterScannerMatchesGoldens) {
    for (auto const& r : kScanRows) {
        auto got = centerScanner(r.bx, r.bz, r.radius);
        ASSERT_EQ(got.size(), r.centers.size()) << "scan " << r.bx << "," << r.bz << " r" << r.radius;
        for (std::size_t i = 0; i < got.size(); ++i) {
            EXPECT_EQ(got[i].x, r.centers[i].first) << "scan item " << i;
            EXPECT_EQ(got[i].z, r.centers[i].second) << "scan item " << i;
        }
    }
}

TEST(LandmarkGrid, BlockNearCenterKeepsJavaPrecedence) {
    // blockX >> 4 + x is blockX >> (4 + x): range 0 is the block's own chunk
    EXPECT_EQ(blockNearCenter(8, 8, 0), chunkHasCenter(0, 0));
    EXPECT_TRUE(blockNearCenter(8, 8, 1));
}

TEST(LandmarkGrid, UnimplementedKeys) {
    for (auto k : {"twilightforest:quest_island", "twilightforest:druid_grove", "twilightforest:floating_ruins", "twilightforest:world_tree"})
        EXPECT_TRUE(isUnimplementedKey(k));
    EXPECT_FALSE(isUnimplementedKey("twilightforest:lich_tower"));
}

TEST(LandmarkGrid, JavaRandomMatchesJavaUtilRandom) {
    // new java.util.Random(42): nextInt() = -1170105035, nextInt(10) = 3 (0 after), nextLong ...
    JavaRandom r(42);
    EXPECT_EQ(r.nextInt(), -1170105035);
    JavaRandom r2(42);
    EXPECT_EQ(r2.nextInt(10), 0);
    JavaRandom r3(0);
    EXPECT_EQ(r3.nextInt(), -1155484576);
    JavaRandom r4(0);
    EXPECT_EQ(r4.nextLong(), -4962768465676381896LL);
}
